import streamDeck, {
  SingletonAction,
  type DialAction,
  type DidReceiveSettingsEvent,
  type FeedbackPayload,
  type KeyAction,
  type WillAppearEvent,
  type WillDisappearEvent,
} from "@elgato/streamdeck";

import { faceImage } from "../face.ts";
import { GLYPHS } from "../glyphs.ts";
import { sayWho, store, wire } from "../plugin.ts";
import type { DeckState, Face } from "../state.ts";

/**
 * The JSON shape Stream Deck persists, mirrored rather than imported.
 *
 * `SingletonAction` constrains its settings to `@elgato/utils`' `JsonObject`,
 * which `@elgato/streamdeck` does not re-export; this is the same type,
 * structurally, without depending on a package the plugin does not declare.
 */
type JsonPrimitive = boolean | number | string | null | undefined;
type JsonValue = JsonObject | JsonPrimitive | JsonValue[];
export type JsonObject = { [key: string]: JsonValue };

/** How long a press waits for the server's verdict before giving up on it. */
const VERDICT_MS = 5000;

/** Either kind of placed action - a key on the grid, or a dial on a Stream Deck +. */
export type Placed<S extends JsonObject> = DialAction<S> | KeyAction<S>;

/**
 * What every Runlog action has in common: one state, one wire, one drawing.
 *
 * A subclass says only what its face is. Redrawing is a subscription to the
 * store held while any instance of the action is placed, so a key follows
 * the run without knowing anything about the socket behind it.
 */
export abstract class RunlogAction<S extends JsonObject = JsonObject> extends SingletonAction<S> {
  private unsub: (() => void) | null = null;
  /** What each placement last said, so a change is logged once and a redraw that says the same thing is not. */
  private said = new Map<string, string>();

  /** What this action says, given everything the plugin knows. */
  abstract face(state: DeckState, settings: S, now: number): Face;

  /**
   * The drawing this action wears in the corner of its keys.
   *
   * By the last word of the UUID, which is the name its SVG is filed under
   * in `design/actions`: one home for the pairing, and a new action gets
   * its glyph by being named after its drawing rather than by a table.
   */
  private glyph(): string | undefined {
    return GLYPHS[this.manifestId?.split(".").pop() ?? ""];
  }

  override async onWillAppear(ev: WillAppearEvent<S>): Promise<void> {
    this.unsub ??= store.subscribe(() => this.redrawAll());
    const face = this.face(store.state, ev.payload.settings, Date.now());
    // What a key came up saying, which is the only way to read the deck from
    // a log. Once per placement, not once per redraw.
    streamDeck.logger.info(`appeared: ${this.manifestId ?? "?"} says "${face.title}"`);
    await this.draw(ev.action, ev.payload.settings);
  }

  override onWillDisappear(_ev: WillDisappearEvent<S>): void {
    if (this.actions.length > 0) return;
    this.unsub?.();
    this.unsub = null;
  }

  /** A setting changed in the inspector redraws the key it was changed for. */
  override async onDidReceiveSettings(ev: DidReceiveSettingsEvent<S>): Promise<void> {
    await this.draw(ev.action, ev.payload.settings);
  }

  /** Every inspector carries the account block, so every inspector is told who is signed in. */
  override async onPropertyInspectorDidAppear(): Promise<void> {
    await sayWho();
  }

  protected async draw(action: Placed<S>, settings: S): Promise<void> {
    // The whole redraw is inside the try, the face included: a state a
    // face was not written for, an image the software will not take, a
    // dial that went away mid-write. The SDK's uncaughtException handler
    // is registered `once`, so the second throw anywhere in here would be
    // the plugin's last.
    try {
      const face = this.face(store.state, settings, Date.now());
      if (this.said.get(action.id) !== face.title) {
        this.said.set(action.id, face.title);
        streamDeck.logger.info(
          `${this.manifestId ?? "?"} ${action.id} (${action.controllerType}) now says "${face.title}" for ${JSON.stringify(settings)}`,
        );
      }
      if (action.isKey()) {
        await action.setImage(faceImage(face, this.glyph()));
        await action.setTitle("");
      } else if (action.isDial()) {
        // The `$B1` layout's progress bar is the `indicator` key; it only
        // has something to show for a running timer's fraction, controller
        // ruling 4 - anything else leaves it out rather than drawing an
        // empty bar.
        const feedback: FeedbackPayload = { title: face.when ?? "", value: face.title };
        if (face.fraction !== undefined) feedback.indicator = { value: Math.round(face.fraction * 100) };
        await action.setFeedback(feedback);
      }
    } catch (error) {
      // The software answers nothing on a bad image; a throw here is the
      // only word of it there is, and it is worth a line in the log.
      streamDeck.logger.error(`could not draw ${action.id}: ${String(error)}`);
    }
  }

  private redrawAll(): void {
    // The settings read can reject too, and a rejection with nothing on it
    // is an unhandled one.
    for (const a of this.actions)
      void a
        .getSettings<S>()
        .then((s) => this.draw(a, s))
        .catch((error) => streamDeck.logger.error(`could not redraw ${a.id}: ${String(error)}`));
  }

  /**
   * A press, with the flash the server's answer will turn into.
   *
   * The wait is bounded two ways, because a verdict that never comes would
   * otherwise leave a listener on the store for the life of the plugin: the
   * deck going off ends it silently, and a press still unanswered after
   * {@link VERDICT_MS} ends it with the alert - a press that vanished should
   * say so rather than nothing.
   */
  protected async send(action: Placed<S>, p: Parameters<typeof wire.press>[0]): Promise<void> {
    const ref = wire.press(p);
    if (!ref) {
      await action.showAlert();
      return;
    }
    let off: (() => void) | null = null;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const stop = (): boolean => {
      if (off === null) return false;
      if (timer) clearTimeout(timer);
      off();
      off = null;
      return true;
    };
    off = store.subscribe((s) => {
      if (!s.on) {
        stop();
        return;
      }
      if (s.flash?.ref !== ref) return;
      const ok = s.flash.ok;
      if (!stop()) return;
      void (ok && action.isKey() ? action.showOk() : action.showAlert());
    });
    timer = setTimeout(() => {
      if (stop()) void action.showAlert();
    }, VERDICT_MS);
  }
}
import streamDeck, { action, type DialRotateEvent } from "@elgato/streamdeck";

import { store } from "../plugin.ts";
import { metricFace, type DeckState, type Face, type MetricField } from "../state.ts";
import { RunlogAction } from "./base.ts";

export type MetricSettings = { field?: MetricField };

/** The fields a dial cycles through. A counter or resource is the run's own and is not on this wheel. */
const FIELDS = ["score", "unit", "clock", "latest", "leader"] as const;

/** The field a dial's rotation lands on, wrapping both ways. */
export function nextField(field: MetricField, by: number): MetricField {
  const i = typeof field === "string" ? FIELDS.indexOf(field) : -1;
  return FIELDS[(i + by + FIELDS.length) % FIELDS.length]!;
}

/** A number from the run: the score, the unit, a clock, the last result, the leader. */
@action({ UUID: "com.scrthq.runlog.metric" })
export class Metric extends RunlogAction<MetricSettings> {
  face(state: DeckState, settings: MetricSettings, now: number): Face {
    return settings.field ? metricFace(state, settings.field, now) : { title: "Set up", tone: "dim" };
  }

  /** Rotating a dial steps its field and redraws at once. */
  override async onDialRotate(ev: DialRotateEvent<MetricSettings>): Promise<void> {
    const field = nextField(ev.payload.settings.field ?? "score", Math.sign(ev.payload.ticks));
    await ev.action.setSettings({ field });
    await this.draw(ev.action, { field });
  }

  /** The fixed fields are known to the inspector; the counters and resources are the run's own. */
  override async onPropertyInspectorDidAppear(): Promise<void> {
    await super.onPropertyInspectorDidAppear();
    const snap = store.state.snapshot;
    await streamDeck.ui.sendToPropertyInspector({
      t: "fields",
      counters: snap?.counters?.map((c) => ({ id: c.id, label: c.label })) ?? [],
      resources: snap?.resources?.map((r) => ({ id: r.id, label: r.label })) ?? [],
    });
  }
}
import { action, type KeyDownEvent } from "@elgato/streamdeck";

import { store } from "../plugin.ts";
import { rollFace, type DeckState, type Face } from "../state.ts";
import { RunlogAction } from "./base.ts";

/** Throws the dice the run is waiting on - Press's roll target, on a key of its own. */
@action({ UUID: "com.scrthq.runlog.roll" })
export class Roll extends RunlogAction {
  face(state: DeckState): Face {
    return rollFace(state);
  }

  override async onKeyDown(ev: KeyDownEvent): Promise<void> {
    if (store.state.snapshot?.offer?.primary?.id !== "roll") {
      await ev.action.showAlert();
      return;
    }
    await this.send(ev.action, { press: "primary" });
  }
}
import streamDeck, { action, type KeyDownEvent } from "@elgato/streamdeck";

import { apiBase, store } from "../plugin.ts";
import { attachedRun, openFace, type DeckState, type Face, type OpenTarget } from "../state.ts";
import { RunlogAction } from "./base.ts";

export type OpenSettings = { target?: OpenTarget };

/**
 * Opens a page in the streamer's browser: the run, the guide, or the
 * pack's rules.
 *
 * The only key that does not press anything. Every address is built off
 * the plugin's own base, so a deck pointed at a copy of Runlog opens that
 * copy's pages rather than the hosted one.
 */
@action({ UUID: "com.scrthq.runlog.open" })
export class Open extends RunlogAction<OpenSettings> {
  face(state: DeckState, settings: OpenSettings): Face {
    return openFace(state, settings.target);
  }

  override async onKeyDown(ev: KeyDownEvent<OpenSettings>): Promise<void> {
    const url = this.url(ev.payload.settings.target);
    if (!url) {
      await ev.action.showAlert();
      return;
    }
    streamDeck.system.openUrl(url);
    await ev.action.showOk();
  }

  /** The page this key was set to, or nothing where the deck is not holding what it needs. */
  private url(target?: OpenTarget): string | null {
    const base = apiBase();
    // The guide is readable whatever the deck is holding, so it is answered
    // before anything is asked of the run.
    if (target === "guide") return `${base}/guide/stream-deck`;
    if (target === "run") {
      const run = attachedRun(store.state);
      return run ? `${base}/run/${encodeURIComponent(run)}` : null;
    }
    if (target === "rules") {
      // The docs drawer's own address, which opens the pack's summary.
      const packId = store.state.snapshot?.run?.packId;
      return packId ? `${base}/packs/${encodeURIComponent(packId)}/docs` : null;
    }
    return null;
  }
}
import { action, type DialDownEvent, type KeyDownEvent, type TouchTapEvent } from "@elgato/streamdeck";

import { store } from "../plugin.ts";
import { nextFace, nextPress, type DeckState, type Face, type NextSettings } from "../state.ts";
import { RunlogAction, type Placed } from "./base.ts";

export type { NextSettings };

/** Whatever the run is waiting on, pressed - the decisions with it, unless told to stop. */
@action({ UUID: "com.scrthq.runlog.next" })
export class Next extends RunlogAction<NextSettings> {
  face(state: DeckState, settings: NextSettings): Face {
    return nextFace(state, settings);
  }

  /**
   * One press, whichever of the three it turns out to be.
   *
   * There is no local refusal to show: a press with nothing to take goes as
   * the bare primary, and the page refuses it in its own words, which is
   * what the face is already saying.
   */
  private async take(placed: Placed<NextSettings>, settings: NextSettings): Promise<void> {
    await this.send(placed, nextPress(store.state, settings) ?? { press: "primary" });
  }

  override async onKeyDown(ev: KeyDownEvent<NextSettings>): Promise<void> {
    await this.take(ev.action, ev.payload.settings);
  }

  override async onTouchTap(ev: TouchTapEvent<NextSettings>): Promise<void> {
    await this.take(ev.action, ev.payload.settings);
  }

  override async onDialDown(ev: DialDownEvent<NextSettings>): Promise<void> {
    await this.take(ev.action, ev.payload.settings);
  }
}

